package io.github.jimbozoomer.jugcraft.wilds;
import io.github.jimbozoomer.jugcraft.Jugcraft;
import io.github.jimbozoomer.jugcraft.backpack.OwnerBackpacks;
import java.util.*;
import net.fabricmc.fabric.api.creativetab.v1.CreativeModeTabEvents;
import net.fabricmc.fabric.api.registry.FlammableBlockRegistry;
import net.minecraft.core.*;
import net.minecraft.core.registries.*;
import net.minecraft.resources.ResourceKey;
import net.minecraft.sounds.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.state.BlockBehaviour;

/** Native behavior bindings for the owner's creature collection, not an external-mod runtime. */
public final class OwnerWilds {
    public static net.minecraft.world.level.block.entity.BlockEntityType<WildGong> GONG;
    public static final Map<String,Block> BLOCKS=new LinkedHashMap<>();
    public static final Map<String,Item> ITEMS=new LinkedHashMap<>();
    private static final Map<String,SoundEvent> SOUNDS=new HashMap<>();
    public static Item item(String name){return ITEMS.getOrDefault(name,Items.AIR);}
    public static Block block(String name){return BLOCKS.getOrDefault(name,Blocks.AIR);}
    public static SoundEvent sound(String name){return SOUNDS.getOrDefault(name,SoundEvents.GRASS_BREAK);}
    public static void register(){
        var data=OwnerBackpacks.source("newest_wilds.json");
        for(var e:data.getAsJsonArray("sounds")){String n=e.getAsString();var id=Jugcraft.id("wilds_"+n);SOUNDS.put(n,Registry.register(BuiltInRegistries.SOUND_EVENT,id,SoundEvent.createVariableRangeEvent(id)));}
        for(var e:data.getAsJsonArray("blocks")){String n=e.getAsString();var key=ResourceKey.create(Registries.BLOCK,Jugcraft.id("wilds_"+n));boolean sand=n.endsWith("raked_sand");var base=sand?(n.startsWith("red_")?Blocks.RED_SAND:Blocks.SAND):n.equals("thatch_block")?Blocks.HAY_BLOCK:n.equals("clawed_log")?Blocks.ACACIA_LOG:Blocks.ACACIA_PLANKS;var p=BlockBehaviour.Properties.ofFullCopy(base).setId(key);if(n.equals("clawed_log"))p.mapColor(net.minecraft.world.level.material.MapColor.WOOD);
            Block b=n.startsWith("gong")?new WildGong.GongBlock(n.equals("gong"),BlockBehaviour.Properties.ofFullCopy(Blocks.IRON_BLOCK).strength(5).setId(key)):sand?new WildRakedSand(n.startsWith("red_"),p):n.endsWith("_slab")?new SlabBlock(p):n.equals("thatch_block")?new HayBlock(p):new Block(p);Registry.register(BuiltInRegistries.BLOCK,key.identifier(),b);BLOCKS.put(n,b);if(n.equals("gong_part"))continue;var ik=ResourceKey.create(Registries.ITEM,key.identifier());ITEMS.put(n,Registry.register(BuiltInRegistries.ITEM,ik,new BlockItem(b,new Item.Properties().setId(ik).useBlockDescriptionPrefix())));if(!sand&&!n.equals("gong"))FlammableBlockRegistry.getDefaultInstance().add(b,n.equals("thatch_block")?60:5,n.equals("clawed_log")?5:20);
        }
        GONG=Registry.register(BuiltInRegistries.BLOCK_ENTITY_TYPE,Jugcraft.id("wilds_gong"),net.fabricmc.fabric.api.object.builder.v1.block.entity.FabricBlockEntityTypeBuilder.create(WildGong::new,block("gong")).build());
        WildFoliaath.register();WildGrottol.register();WildLantern.register();WildWeapons.register();WildNaga.register();WildWroughtnaut.register();WildWroughtEquipment.register();WildFrostmaw.register();WildFrostSite.register();WildBluff.register();WildMoonEffects.register();WildParticles.register();WildElokosa.register();WildSolar.register();WildSunEquipment.register();WildUmvuthana.register();WildUmvuthi.register();WildGrove.register();WildMonastery.register();WildBoulder.register();WildSculptor.register();WildEarthEquipment.register();
        for(var e:data.getAsJsonArray("items")){String n=e.getAsString();var key=ResourceKey.create(Registries.ITEM,Jugcraft.id("wilds_"+n));var p=new Item.Properties().setId(key);Item item=switch(n){case "grant_suns_blessing"->new Item(p){@Override public net.minecraft.world.InteractionResult use(net.minecraft.world.level.Level l,net.minecraft.world.entity.player.Player player,net.minecraft.world.InteractionHand hand){if(!l.isClientSide())player.addEffect(new net.minecraft.world.effect.MobEffectInstance(WildSunEquipment.BLESSING,-1,0,false,false));return net.minecraft.world.InteractionResult.SUCCESS;}};case "earthrend_gauntlet"->new WildEarthEquipment.Gauntlet(p);case "sculptor_staff"->new WildEarthEquipment.Staff(p);case "geomancer_beads"->new WildEarthEquipment.Armor(net.minecraft.world.item.equipment.ArmorType.HELMET,p);case "geomancer_robe"->new WildEarthEquipment.Armor(net.minecraft.world.item.equipment.ArmorType.CHESTPLATE,p);case "geomancer_belt"->new WildEarthEquipment.Armor(net.minecraft.world.item.equipment.ArmorType.LEGGINGS,p);case "geomancer_sandals"->new WildEarthEquipment.Armor(net.minecraft.world.item.equipment.ArmorType.BOOTS,p);case "sculptor_spawn_egg"->new SpawnEggItem(p.spawnEgg(WildSculptor.TYPE));case "umvuthi_spawn_egg"->new SpawnEggItem(p.spawnEgg(WildUmvuthi.TYPE));case "umvuthana_spawn_egg"->new SpawnEggItem(p.spawnEgg(WildUmvuthana.TYPE));case "umvuthana_raptor_spawn_egg"->new SpawnEggItem(p.spawnEgg(WildUmvuthana.RAPTOR));case "umvuthana_crane_spawn_egg"->new SpawnEggItem(p.spawnEgg(WildUmvuthana.CRANE));case "sol_visage"->new WildSunEquipment.Mask(0,true,p);case "umvuthana_mask_fury","umvuthana_mask_fear","umvuthana_mask_rage","umvuthana_mask_bliss","umvuthana_mask_misery","umvuthana_mask_faith"->new WildSunEquipment.Mask(java.util.Arrays.asList(WildUmvuthana.MASKS).indexOf(n.substring("umvuthana_mask_".length())),false,p);case "elokosa_howler_spawn_egg"->new SpawnEggItem(p.spawnEgg(WildElokosa.HOWLER));case "elokosa_spawn_egg"->new SpawnEggItem(p.spawnEgg(WildElokosa.FOLLOWER));case "elokosa_paw_full","elokosa_paw_gibbous","elokosa_paw_half","elokosa_paw_crescent","elokosa_paw_new"->new WildMoonEffects.Paw(java.util.Arrays.asList(WildMoonEffects.PAWS).indexOf(n.substring("elokosa_paw_".length())),p);case "bluff_spawn_egg"->new SpawnEggItem(p.spawnEgg(WildBluff.TYPE));case "ice_crystal"->new WildCold.Crystal(p);case "frostmaw_spawn_egg"->new SpawnEggItem(p.spawnEgg(WildFrostmaw.TYPE));case "music_disc_petiole"->new Item(p.stacksTo(1).rarity(Rarity.RARE).jukeboxPlayable(ResourceKey.create(Registries.JUKEBOX_SONG,Jugcraft.id("wilds_petiole"))));case "wrought_axe"->new WildWroughtEquipment.Axe(p);case "wrought_helmet"->new WildWroughtEquipment.Helmet(p);case "wroughtnaut_spawn_egg"->new SpawnEggItem(p.spawnEgg(WildWroughtnaut.TYPE));case "foliaath_seed"->new WildFoliaath.Seed(p);case "dart"->WildWeapons.dart(p);case "blowgun"->new WildWeapons.Blowgun(p);case "spear"->WildWeapons.melee(false,p);case "naga_fang_dagger"->WildWeapons.melee(true,p);case "captured_grottol"->new WildGrottol.Captured(p);case "grottol_spawn_egg"->new SpawnEggItem(p.spawnEgg(WildGrottol.TYPE));case "naga_spawn_egg"->new SpawnEggItem(p.spawnEgg(WildNaga.TYPE));case "lantern_spawn_egg"->new SpawnEggItem(p.spawnEgg(WildLantern.TYPE));case "glowing_jelly"->new Item(p.food(new net.minecraft.world.food.FoodProperties.Builder().nutrition(1).saturationModifier(.1F).alwaysEdible().build(),net.minecraft.world.item.component.Consumables.defaultFood().onConsume(new net.minecraft.world.item.consume_effects.ApplyStatusEffectsConsumeEffect(new net.minecraft.world.effect.MobEffectInstance(net.minecraft.world.effect.MobEffects.GLOWING,1200),1)).build()));case "sand_rake"->new WildRakedSand.Rake(p);case "foliaath_spawn_egg"->new WildFoliaath.Seed(true,p);default->new Item(p);};ITEMS.put(n,Registry.register(BuiltInRegistries.ITEM,key,item));}
        DispenserBlock.registerProjectileBehavior(item("dart"));
        CreativeModeTabEvents.modifyOutputEvent(CreativeModeTabs.BUILDING_BLOCKS).register(e->BLOCKS.forEach((n,b)->{if(!n.equals("gong_part"))e.accept(b);}));
        CreativeModeTabEvents.modifyOutputEvent(CreativeModeTabs.TOOLS_AND_UTILITIES).register(e->ITEMS.forEach((n,i)->{if(!BLOCKS.containsKey(n))e.accept(i);}));
    }
}
